import React,{useEffect,useMemo,useState,useCallback} from 'react';
import {createRoot} from 'react-dom/client';
import {LayoutDashboard,ListTodo,Server,Wallet,ShieldCheck,Settings as SettingsIcon,Plus,RefreshCw,LogOut,Menu,X,Check,AlertTriangle,Clock,Activity,HardDrive,Cpu,MemoryStick,TrendingUp,TrendingDown,ArrowLeft,Pencil,Trash2,Download,Upload,Link2,ExternalLink,Coins,CircleCheck,Search,Save,KeyRound,Database,Wifi,WifiOff,Eye,BookOpen,CalendarDays,ChevronDown,SlidersHorizontal} from 'lucide-react';
import './styles.css';

const PA=[['overview','نمای کلی',LayoutDashboard],['tasks','کارهای روزانه',ListTodo],['servers','مدیریت سرورها',Server],['finance','مدیریت مالی',Wallet],['owasp','کلاس OWASP',ShieldCheck],['settings','تنظیمات و پشتیبان',SettingsIcon]];
const fmt=new Intl.NumberFormat('fa-IR',{maximumFractionDigits:2});const fmt0=new Intl.NumberFormat('fa-IR',{maximumFractionDigits:0});
const numeric=x=>Number(x)||0;
const money=v=>fmt0.format(Math.round(numeric(v)))+' تومان';
const shortMoney=x=>Math.abs(x)>=1e9?fmt.format(x/1e9)+' میلیارد':Math.abs(x)>=1e6?fmt.format(x/1e6)+' میلیون':Math.abs(x)>=1e3?fmt.format(x/1e3)+' هزار':fmt.format(x);
const pct=(a,b)=>numeric(b)>0?Math.min(100,Math.max(0,100*numeric(a)/numeric(b))):0;
const dateOnly=d=>String(d||'').slice(0,10);
const faDate=d=>{if(!d)return '—';try{return new Intl.DateTimeFormat('fa-IR-u-ca-persian',{day:'numeric',month:'short',year:'numeric'}).format(new Date(d))}catch{return '—'}};
const faDateTime=d=>{if(!d)return 'ثبت نشده';try{return new Intl.DateTimeFormat('fa-IR-u-ca-persian',{year:'numeric',month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(d))}catch{return 'نامشخص'}};
const monthKey=d=>new Intl.DateTimeFormat('en-US-u-ca-persian',{year:'numeric',month:'2-digit'}).formatToParts(new Date(d)).filter(p=>['year','month'].includes(p.type)).map(p=>p.value).join('-');
const statusText={todo:'شروع نشده',progress:'در حال انجام',review:'نیازمند بررسی',done:'تکمیل‌شده',pending:'بررسی‌نشده',verified:'تأییدشده',broken:'نامعتبر'};
const priorityText={low:'کم',medium:'متوسط',high:'بالا'};
const sections={work:'کاری',personal:'شخصی',server:'سرور',owasp:'آموزش OWASP',finance:'مالی'};
const badge=(v)=>statusText[v]||v||'—';
const cn=(...x)=>x.filter(Boolean).join(' ');
const EMPTY={tasks:[],servers:[],transactions:[],installments:[],holdings:[],currencies:[],chapters:[],topics:[],resources:[],activities:[],rates:[],priceHistory:[]};
let csrf='';
async function api(url,opts={}){const resp=await fetch('/api'+url,{credentials:'same-origin',...opts,headers:{...(opts.body?{'Content-Type':'application/json'}:{}),...(!['GET','HEAD'].includes(opts.method||'GET')?{'X-CSRF-Token':csrf}:{}),...(opts.headers||{})}});const json=await resp.json().catch(()=>({}));if(resp.status===401&&url!=='/auth/status'&&url!=='/login')window.dispatchEvent(new Event('markaz:expired'));if(!resp.ok)throw Error(json.error||'خطای سرویس '+resp.status);return json;}
const request=(method,url,body)=>api(url,{method,body:body===undefined?undefined:JSON.stringify(body)});
function App(){
 const [auth,setAuth]=useState(null),[username,setUsername]=useState(''),[password,setPassword]=useState(''),[setupRequired,setSetupRequired]=useState(false),[setupCode,setSetupCode]=useState(''),[setupUser,setSetupUser]=useState(''),[setupPass,setSetupPass]=useState(''),[setupConfirm,setSetupConfirm]=useState(''),[authError,setAuthError]=useState(''),[loading,setLoading]=useState(true),[data,setData]=useState(EMPTY),[page,setPage]=useState('overview'),[drawer,setDrawer]=useState(false),[modal,setModal]=useState(null),[financeTab,setFinanceTab]=useState('transactions'),[search,setSearch]=useState(''),[toast,setToast]=useState(''),[busy,setBusy]=useState(false),[installPrompt,setInstallPrompt]=useState(null),[isOnline,setIsOnline]=useState(navigator.onLine),[provider,setProvider]=useState({configured:false,unit:'RIAL',refreshHours:8}),[arzdigital,setArzdigital]=useState({enabled:false,configured:false,endpoint:'',unit:'TOMAN',refreshHours:8,rootPath:'data',priceField:'price',codeField:'symbol',authStyle:'bearer'}),[rateSource,setRateSource]=useState({selected:'nerkhara',refreshMinutes:15});
 const alert=useCallback(msg=>{setToast(msg);setTimeout(()=>setToast(''),4200)},[]);
 const load=useCallback(async()=>{const result=await api('/dashboard');setData(result)},[]);
 useEffect(()=>{const online=()=>setIsOnline(navigator.onLine);window.addEventListener('online',online);window.addEventListener('offline',online);const expired=()=>setAuth(false);window.addEventListener('markaz:expired',expired);api('/auth/status').then(x=>{setAuth(x.authenticated);setSetupRequired(Boolean(x.needsSetup));setUsername(x.username||'');csrf=x.csrf||'';setAuthError('');if(x.authenticated)load().catch(e=>alert(e.message))}).catch(e=>{setAuth(false);setAuthError('ارتباط با پایگاه‌داده یا سرور برقرار نیست: '+e.message)}).finally(()=>setLoading(false));if('serviceWorker'in navigator&&import.meta.env.PROD)navigator.serviceWorker.register('/sw.js').catch(()=>{});const installer=e=>{e.preventDefault();setInstallPrompt(e)};window.addEventListener('beforeinstallprompt',installer);return()=>{window.removeEventListener('online',online);window.removeEventListener('offline',online);window.removeEventListener('beforeinstallprompt',installer);window.removeEventListener('markaz:expired',expired)}},[load,alert]);
 useEffect(()=>{if(auth){api('/settings/provider').then(setProvider).catch(()=>{});api('/settings/arzdigital').then(setArzdigital).catch(()=>{});api('/settings/rate-source').then(setRateSource).catch(()=>{})}},[auth]);
 async function login(e){e.preventDefault();setBusy(true);try{const x=await request('POST','/login',{username,password});csrf=x.csrf;setUsername(x.username);setAuth(true);setPassword('');await load();alert('ورود انجام شد')}catch(e){alert(e.message)}finally{setBusy(false)}}
 async function firstSetup(e){e.preventDefault();if(setupPass!==setupConfirm){alert('تکرار رمز با رمز عبور یکسان نیست');return}setBusy(true);try{const x=await request('POST','/setup',{setupCode:setupCode.trim().toLowerCase(),username:setupUser,password:setupPass,confirm:setupConfirm});csrf=x.csrf;setUsername(x.username);setAuth(true);setSetupRequired(false);setSetupCode('');setSetupPass('');setSetupConfirm('');await load();alert('حساب مدیر ساخته شد و راه‌اندازی اولیه بسته شد')}catch(e){if(e.message.includes('قبلاً ساخته شده')){setSetupRequired(false);setSetupCode('');alert('حساب مدیر قبلاً ایجاد شده؛ وارد شوید')}else alert(e.message)}finally{setBusy(false)}}
 async function logout(){try{await request('POST','/logout',{})}catch{}csrf='';setAuth(false);setData(EMPTY);setPage('overview')}
 async function run(fn,ok='تغییرات ذخیره شد'){setBusy(true);try{await fn();await load();setModal(null);alert(ok)}catch(e){alert(e.message)}finally{setBusy(false)}}
 async function save(kind,values,orig){await run(()=>request(orig?'PUT':'POST',`/${kind}${orig?'/'+encodeURIComponent(orig.id||orig.code):''}`,values))}
 async function remove(kind,obj){if(!window.confirm('این مورد حذف شود؟'))return;await run(()=>request('DELETE',`/${kind}/${encodeURIComponent(obj.id||obj.code)}`,{}),'مورد حذف شد')}
 const txThisMonth=useMemo(()=>{const current=monthKey(new Date());return data.transactions.filter(t=>t.date&&monthKey(t.date)===current)},[data.transactions]);
 const income=txThisMonth.filter(t=>t.type==='income').reduce((s,t)=>s+numeric(t.amount),0);const expenses=txThisMonth.filter(t=>t.type!=='income').reduce((s,t)=>s+numeric(t.amount),0);
 const remaining=data.installments.reduce((s,t)=>s+Math.max(0,numeric(t.total)-numeric(t.paid)),0);
 const rateBy=Object.fromEntries(data.rates.map(r=>[r.code,r]));const currBy=Object.fromEntries(data.currencies.map(c=>[c.code,c]));
 const portfolio=data.holdings.reduce((s,h)=>s+numeric(h.quantity)*numeric(rateBy[h.asset]?.price),0);
 const noRate=data.holdings.filter(h=>!numeric(rateBy[h.asset]?.price)).length;
 const taskDone=data.tasks.filter(t=>t.status==='done').length;const taskOpen=data.tasks.length-taskDone;const reviewTasks=data.tasks.filter(t=>t.status==='review');
 const chapDone=data.chapters.filter(c=>c.status==='done').length;const resourcesReview=data.resources.filter(r=>r.status!=='verified');
 const nav=label=>{setPage(label);setDrawer(false);setSearch('')};
 function fieldModal(kind,item=null,extras={}){setModal({kind,item,extras})}
 const openNew=()=>{if(page==='overview'||page==='tasks')fieldModal('tasks');else if(page==='servers')fieldModal('servers');else if(page==='finance')fieldModal(financeTab==='savings'?'holdings':financeTab==='installments'?'installments':financeTab==='currencies'?'currencies':'transactions');else if(page==='owasp')fieldModal('chapters')};
 if(loading)return <div className="loading-screen"><div className="spinner"/>در حال راه‌اندازی…</div>;
 if(!auth)return <div className="login-layout"><div className="login-panel"><div className="login-brand"><span className="logo">م</span><div><strong>مرکز</strong><small>داشبورد شخصی React + PostgreSQL</small></div></div>
 {authError?<><h1>اتصال برقرار نیست</h1><p className="form-error">{authError}</p><button className="primary" onClick={()=>window.location.reload()}>تلاش مجدد</button></>:setupRequired?<><div className="setup-marker"><ShieldCheck size={17}/> راه‌اندازی یک‌باره</div><h1>ایجاد حساب مدیر</h1><p>اولین بار است که پنل باز می‌شود. نام کاربری و رمز عبور دلخواه را تعیین کنید. کد راه‌اندازی اختصاصی در پایان نصب سرور نمایش داده شده و در فایل امن <code>.env</code> قرار دارد.</p><form onSubmit={firstSetup} className="form stack">
 <label>نام کاربری مدیر<input autoFocus dir="ltr" autoCapitalize="none" autoCorrect="off" spellCheck={false} autoComplete="username" type="text" value={setupUser} onChange={e=>setSetupUser(e.target.value)} pattern="[a-zA-Z][a-zA-Z0-9_.-]{2,31}" title="۳ تا ۳۲ نویسه لاتین؛ آغاز با حرف" required minLength={3} maxLength={32} placeholder="myadmin" /></label>
 <label>رمز عبور مدیر<input type="password" autoComplete="new-password" value={setupPass} onChange={e=>setSetupPass(e.target.value)} required minLength={12} maxLength={256} placeholder="حداقل ۱۲ نویسه" /></label>
 <label>تکرار رمز عبور<input type="password" autoComplete="new-password" value={setupConfirm} onChange={e=>setSetupConfirm(e.target.value)} required minLength={12} maxLength={256}/></label>
 <label>کد راه‌اندازی اولیه<input type="password" dir="ltr" autoComplete="off" spellCheck={false} value={setupCode} onChange={e=>setSetupCode(e.target.value)} required minLength={64} maxLength={64} placeholder="SETUP_TOKEN" /></label>
 <button className="primary full" disabled={busy}><ShieldCheck size={17}/> {busy?'در حال ثبت…':'ساخت حساب مدیر و ورود'}</button></form><div className="setup-note"><KeyRound size={16}/> برای جلوگیری از تصاحب پنل، این کد فقط قبل از ساخت اولین حساب کاربرد دارد.</div></>:<><h1>ورود به فضای کاری</h1><p>مدیریت سرورها، پروژه‌ها، امور مالی و کلاس OWASP در یک محیط فارسی.</p><form onSubmit={login} className="form stack"><label>نام کاربری مدیر<input autoFocus dir="ltr" autoCapitalize="none" autoCorrect="off" spellCheck={false} type="text" autoComplete="username" value={username} onChange={e=>setUsername(e.target.value)} required minLength={3} maxLength={32} placeholder="نام کاربری"/></label><label>رمز عبور مدیر<input type="password" autoComplete="current-password" value={password} onChange={e=>setPassword(e.target.value)} required /></label><button className="primary full" disabled={busy}><KeyRound size={17}/> ورود ایمن</button></form></>}
 <div className="login-footer"><Database size={15}/> اطلاعات در پایگاه‌داده PostgreSQL سرور ذخیره می‌شوند.</div></div><div className="login-art"><div className="login-art-icon"><LayoutDashboard size={56}/></div><h2>مدیریت منظم، یکجا</h2><p>اپلیکیشن قابل نصب روی دسکتاپ و موبایل</p></div>{toast&&<div className="toast">{toast}</div>}</div>;
 return <div className="app">
  {drawer&&<div className="mobile-mask" onClick={()=>setDrawer(false)}/>}
  <aside className={cn('sidebar',drawer&&'sidebar-open')}><div className="brand"><span className="logo">م</span><div><strong>مرکز</strong><small>داشبورد یکپارچه</small></div></div><div className="nav-label">فضای کاری من</div><nav>{PA.slice(0,5).map(([k,t,Icon])=><button key={k} className={cn('nav-link',page===k&&'active')} onClick={()=>nav(k)}><Icon size={19} strokeWidth={1.9}/><span>{t}</span>{k==='tasks'&&taskOpen>0&&<em>{fmt.format(taskOpen)}</em>}</button>)}</nav><div className="nav-label">سیستم</div><nav><button className={cn('nav-link',page==='settings'&&'active')} onClick={()=>nav('settings')}><SettingsIcon size={19}/> تنظیمات و پشتیبان</button></nav><div className="sidebar-bottom"><span className="avatar">ش</span><div><strong>{username||'مدیر سیستم'}</strong><small>{isOnline?'متصل به سرور':'ارتباط قطع است'}</small></div>{isOnline?<Wifi size={17} className="good"/>:<WifiOff size={17} className="danger"/>}</div></aside>
  <div className="workspace"><header className="topbar"><div className="header-leading"><button className="icon-button mobile-only" onClick={()=>setDrawer(true)} aria-label="فهرست"><Menu size={22}/></button><div className="breadcrumb">فضای کاری <span>/</span> <strong>{PA.find(([k])=>k===page)?.[1]}</strong></div></div><div className="header-actions"><div className={cn('connection',isOnline?'good':'danger')}><span className="pulse"/>{isOnline?'آنلاین':'آفلاین'}</div>{installPrompt&&<button className="button small" onClick={async()=>{await installPrompt.prompt();setInstallPrompt(null)}}>نصب وب‌اپ</button>}<button className="button small hide-mobile" disabled={busy} onClick={async()=>{setBusy(true);try{const response=await request('POST','/rates/refresh',{});await load();alert(response.updated?`${fmt.format(response.updated)} نرخ تازه دریافت شد`:response.reason||'نرخ تازه‌ای دریافت نشد')}catch(e){alert(e.message)}finally{setBusy(false)}}}><RefreshCw size={16}/> به‌روزرسانی ارز</button><button className="icon-button" onClick={logout} title="خروج"><LogOut size={19}/></button></div></header>
   <main className="main"><div className="heading"><div><p className="eyebrow">داشبورد مدیریتی / {new Intl.DateTimeFormat('fa-IR-u-ca-persian',{dateStyle:'long'}).format(new Date())}</p><h1>{PA.find(([k])=>k===page)?.[1]}</h1><p className="subtitle">{({overview:'خلاصه‌ای از وضعیت همه بخش‌ها و اقدامات بعدی',tasks:'برنامه‌ریزی و پیگیری کارهای شخصی و پروژه‌ها',servers:'مصرف واقعی یا دستی پردازنده، حافظه و دیسک',finance:'ورودی و خروجی پول، اقساط و سبد دارایی به تومان',owasp:'پیشرفت فصل‌ها، مباحث، منابع و صحت‌سنجی',settings:'اتصال سرویس‌ها، امنیت و نگهداری اطلاعات'})[page]}</p></div>{!['overview','settings'].includes(page)&&<button className="primary" onClick={openNew}><Plus size={18}/> افزودن جدید</button>}</div>
   {page==='overview'&&<><div className="stats-grid"><Stat title="کارهای باز" number={fmt.format(taskOpen)} sub={fmt.format(data.tasks.length)+' وظیفه ثبت‌شده'} icon={ListTodo} tone="blue" progress={pct(taskDone,data.tasks.length)}/><Stat title="ارزش پس‌انداز" number={shortMoney(portfolio)} suffix="تومان" sub={noRate?fmt.format(noRate)+' دارایی بدون نرخ':'محاسبه با نرخ تومان'} icon={Wallet} tone="green"/><Stat title="هزینه ماه" number={shortMoney(expenses)} suffix="تومان" sub="شامل پرداخت اقساط" icon={TrendingDown} tone="orange"/><Stat title="پیشرفت OWASP" number={fmt.format(pct(chapDone,data.chapters.length).toFixed(0))+'٪'} sub={fmt.format(chapDone)+' فصل از '+fmt.format(data.chapters.length)} icon={ShieldCheck} tone="violet" progress={pct(chapDone,data.chapters.length)}/></div><div className="cols-2"><Panel title="کارهای بعدی" aside={<button className="link-button" onClick={()=>nav('tasks')}>همه کارها <ArrowLeft size={15}/></button>}>{data.tasks.filter(t=>t.status!=='done').sort((a,b)=>String(a.due_date||'9999').localeCompare(String(b.due_date||'9999'))).slice(0,6).map(t=><div className="line-item" key={t.id}><button className="tiny-checkbox" title="تکمیل" onClick={()=>save('tasks',{...t,status:'done'},t)}><Check size={14}/></button><div className="grow"><strong>{t.title}</strong><small>{sections[t.category]||'کار'} · {t.due_date?faDate(t.due_date):'بدون موعد'}</small></div><Status value={t.status}/></div>)}{!taskOpen&&<Empty text="کار بازی وجود ندارد"/>}</Panel><Panel title="موارد نیازمند بررسی" aside={<span className="count-label">{fmt.format(reviewTasks.length+resourcesReview.length)} مورد</span>}>{[...reviewTasks.map(x=>({name:x.title,label:'وظیفه',where:'tasks'})),...resourcesReview.map(x=>({name:x.title,label:'منبع OWASP',where:'owasp'}))].slice(0,6).map((r,i)=><div key={i} className="line-item"><AlertTriangle size={19} className="warn"/><div className="grow"><strong>{r.name}</strong><small>{r.label}</small></div><button className="link-button" onClick={()=>nav(r.where)}>بررسی</button></div>)}{reviewTasks.length+resourcesReview.length===0&&<Empty text="مورد بازبینی‌نشده وجود ندارد"/>}</Panel></div><div className="cols-2"><Panel title="نمای مالی این ماه" aside={<button className="link-button" onClick={()=>nav('finance')}>جزئیات <ArrowLeft size={15}/></button>}><div className="finance-snapshot"><div><span>درآمد</span><strong className="good">{money(income)}</strong></div><div><span>خرج و اقساط</span><strong className="danger">{money(expenses)}</strong></div><div><span>خالص جریان نقدی</span><strong>{money(income-expenses)}</strong></div><div><span>تعهد اقساط باقیمانده</span><strong>{money(remaining)}</strong></div></div></Panel><Panel title="آخرین فعالیت‌ها"><ActivityList list={data.activities.slice(0,6)}/></Panel></div><Panel title="وضعیت سرورها" aside={<button className="link-button" onClick={()=>nav('servers')}>مدیریت سرورها <ArrowLeft size={15}/></button>}><div className="server-summaries">{data.servers.slice(0,4).map(s=><div key={s.id}><Server size={19}/><strong>{s.name}</strong><span>{s.metrics?fmt.format(numeric(s.metrics.cpu?.usagePercent))+'٪ CPU':'بدون داده'}</span></div>)}{!data.servers.length&&<Empty text="سروری ثبت نشده است"/>}</div></Panel></>}
   {page==='tasks'&&<Tasks items={data.tasks} search={search} setSearch={setSearch} edit={x=>fieldModal('tasks',x)} remove={x=>remove('tasks',x)} toggle={x=>save('tasks',{...x,status:x.status==='done'?'todo':'done'},x)}/>}
   {page==='servers'&&<Servers servers={data.servers} busy={busy} edit={x=>fieldModal('servers',x)} del={x=>remove('servers',x)} metrics={x=>fieldModal('metrics',x)} connect={x=>fieldModal('agent',x)} poll={x=>run(()=>request('POST',`/servers/${x.id}/poll`,{}),'پایش سرور دریافت شد')}/>}
   {page==='finance'&&<Finance {...{data,financeTab,setFinanceTab,income,expenses,remaining,portfolio,noRate,rateBy,currBy}} add={k=>fieldModal(k)} edit={(k,x)=>fieldModal(k,x)} del={remove} pay={x=>fieldModal('payment',x)} />}
   {page==='owasp'&&<Owasp {...{data,search,setSearch}} edit={(kind,obj=null,extras={})=>fieldModal(kind,obj,extras)} del={remove} check={r=>run(async()=>{const out=await api('/links/check?url='+encodeURIComponent(r.url));await request('PUT','/resources/'+r.id,{...r,status:out.ok?'verified':'broken',checked_at:out.checkedAt})},'وضعیت لینک بررسی شد')}/>}
   {page==='settings'&&<Settings {...{provider,arzdigital,rateSource,busy,alert,username}} rateSourceOpen={()=>fieldModal('rateSource')} arzdigitalOpen={()=>fieldModal('arzdigital')} usernameOpen={()=>fieldModal('username')} providerOpen={()=>fieldModal('provider')} passwordOpen={()=>fieldModal('password')} importOpen={()=>fieldModal('import')} exportData={async()=>{try{const resp=await fetch('/api/export',{credentials:'same-origin'});if(!resp.ok)throw Error('خروجی قابل دریافت نیست');const blob=await resp.blob();const u=URL.createObjectURL(blob);const a=document.createElement('a');a.href=u;a.download='markaz-backup-'+new Date().toISOString().slice(0,10)+'.json';a.click();URL.revokeObjectURL(u)}catch(e){alert(e.message)}}} />}
   </main><footer className="footer">مرکز نسخه ۵.۲ · React / PostgreSQL / PWA <span>تمام نرخ‌های دارایی: تومان</span></footer></div>
   {modal&&<Editor key={modal.kind+'-'+(modal.item?.id||modal.item?.code||'new')} config={modal} data={data} provider={provider} arzdigital={arzdigital} rateSource={rateSource} close={()=>setModal(null)} busy={busy} save={async(v)=>{if(modal.kind==='rateSource'){await run(()=>request('PUT','/settings/rate-source',v));setRateSource(await api('/settings/rate-source'));return}if(modal.kind==='provider'){await run(()=>request('PUT','/settings/provider',v));setProvider(await api('/settings/provider'));return}if(modal.kind==='arzdigital'){await run(()=>request('PUT','/settings/arzdigital',v));setArzdigital(await api('/settings/arzdigital'));return}if(modal.kind==='username'||modal.kind==='password'){
 setBusy(true);
 try{
  await request('POST',modal.kind==='username'?'/account/username':'/account/password',v);
  csrf='';setAuth(false);setUsername('');setPassword('');setModal(null);
  alert(modal.kind==='username'?'نام کاربری تغییر کرد؛ با نام جدید وارد شوید':'رمز تغییر کرد؛ با رمز جدید وارد شوید');
 }catch(e){alert(e.message)}finally{setBusy(false)}return;
}if(modal.kind==='metrics'){const ramTotal=numeric(v.ramTotal)*1024**3,diskTotal=numeric(v.diskTotal)*1024**3;await run(()=>request('PUT',`/servers/${modal.item.id}/metrics`,{cpu:{usagePercent:numeric(v.cpu),cores:numeric(v.cores)},memory:{used:numeric(v.ramUsed)*1024**3,total:ramTotal},disk:{used:numeric(v.diskUsed)*1024**3,total:diskTotal,path:'/'}}));return}if(modal.kind==='agent'){await run(()=>request('POST',`/servers/${modal.item.id}/agent`,v));return}if(modal.kind==='payment'){await run(()=>request('POST',`/installments/${modal.item.id}/pay`,v));return}if(modal.kind==='import'){let d;try{d=JSON.parse(v.file)}catch{throw Error('فرمت JSON معتبر نیست')}await run(()=>request('POST','/import/legacy',d),'اطلاعات پشتیبان وارد شدند');return}await save(modal.kind,{...v,...modal.extras},modal.item)}}/>}
   {toast&&<div className="toast" role="status">{toast}</div>}
  </div>
}
function Stat({title,number,sub,icon:Icon,tone='blue',suffix,progress}){return <div className="stat"><div className="stat-head"><span>{title}</span><span className={'stat-icon '+tone}><Icon size={21}/></span></div><div className="stat-number">{number}</div>{suffix&&<small className="stat-unit">{suffix}</small>}<p>{sub}</p>{progress!==undefined&&<Progress value={progress}/>}</div>}
function Progress({value}){return <div className="progress"><span style={{width:Math.max(0,Math.min(100,value))+'%'}}/></div>}
function Panel({title,aside,children,className=''}){return <section className={cn('panel',className)}><div className="panel-head"><h2>{title}</h2>{aside}</div>{children}</section>}
function Status({value}){return <span className={cn('status','status-'+(value||'todo'))}><span/>{badge(value)}</span>}
function RateSource({rate}){if(!rate)return <>—</>;return <><span className="minor-badge">{rate.source==='نرخ‌آرا'?<a href="https://nerkhara.com/" target="_blank" rel="noopener noreferrer">NerkhAra</a>:rate.source||'—'}</span><small style={{display:'block'}}>{faDateTime(rate.updatedAt)}</small></>}
function Empty({text}){return <div className="empty"><div>◇</div>{text}</div>}
function Actions({onEdit,onDelete}){return <div className="row-actions"><button title="ویرایش" onClick={onEdit}><Pencil size={16}/></button><button title="حذف" className="danger" onClick={onDelete}><Trash2 size={16}/></button></div>}
function ActivityList({list}){return list.length?list.map(a=><div className="line-item activity-row" key={a.id}><span className="activity-symbol"><Activity size={17}/></span><div className="grow"><strong>{a.text}</strong><small>{faDate(a.at)}</small></div></div>):<Empty text="هنوز فعالیتی ثبت نشده است"/>}
function Tasks({items,search,setSearch,edit,remove,toggle}){const [filter,setFilter]=useState('all');const shown=items.filter(t=>(filter==='all'||t.status===filter)&&((t.title+' '+t.notes).toLowerCase().includes(search.toLowerCase())));return <><div className="stats-grid compact"><Stat title="همه کارها" number={fmt.format(items.length)} icon={ListTodo} tone="blue"/><Stat title="کارهای باز" number={fmt.format(items.filter(t=>t.status!=='done').length)} icon={Clock} tone="orange"/><Stat title="تکمیل‌شده" number={fmt.format(items.filter(t=>t.status==='done').length)} icon={CircleCheck} tone="green"/><Stat title="پیشرفت" number={fmt.format(pct(items.filter(t=>t.status==='done').length,items.length).toFixed(0))+'٪'} icon={TrendingUp} tone="violet"/></div><div className="toolbar"><div className="tabs">{[['all','همه'],['todo','شروع نشده'],['progress','در جریان'],['review','بازبینی'],['done','تکمیل']].map(([k,t])=><button key={k} className={filter===k?'selected':''} onClick={()=>setFilter(k)}>{t}</button>)}</div><div className="search"><Search size={17}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="جست‌وجوی کارها"/></div></div><Panel title="فهرست کارهای روزانه" aside={<span className="count-label">{fmt.format(shown.length)} کار</span>}><div className="records">{shown.map(t=><div className="record" key={t.id}><button className={cn('task-checkbox',t.status==='done'&&'checked')} onClick={()=>toggle(t)} aria-label="تغییر وضعیت"><Check size={15}/></button><span className={'priority priority-'+t.priority}/><div className="grow"><strong className={t.status==='done'?'struck':''}>{t.title}</strong><small>{sections[t.category]||'کار'} · اولویت {priorityText[t.priority]} {t.due_date?' · موعد '+faDate(t.due_date):''}</small>{t.notes&&<p className="short-note">{t.notes}</p>}</div><Status value={t.status}/><Actions onEdit={()=>edit(t)} onDelete={()=>remove(t)}/></div>)}{shown.length===0&&<Empty text="کاری مطابق فیلتر پیدا نشد"/>}</div></Panel></>}
function Gauge({name,value,detail}){return <div className="gauge"><div className="gauge-row"><span>{name}</span><strong>{value===null?'—':fmt.format(value)+'٪'}</strong></div><Progress value={value||0}/><small>{detail||'بدون اطلاعات'}</small></div>}
function Servers({servers,busy,edit,del,metrics,connect,poll}){return <><div className="stats-grid compact"><Stat title="سرورهای ثبت‌شده" number={fmt.format(servers.length)} icon={Server}/><Stat title="پایش زنده" number={fmt.format(servers.filter(x=>x.mode==='agent').length)} icon={Activity} tone="green"/><Stat title="دارای اطلاعات" number={fmt.format(servers.filter(x=>x.metrics).length)} icon={Cpu} tone="violet"/><Stat title="بدون داده" number={fmt.format(servers.filter(x=>!x.metrics).length)} icon={AlertTriangle} tone="orange"/></div><div className="server-grid">{servers.map(s=>{const m=s.metrics;const ram=m?pct(m.memory?.used,m.memory?.total):null;const disk=m?pct(m.disk?.used,m.disk?.total):null;return <Panel className="server-panel" key={s.id} title={<><Server size={20}/>{s.name}</>} aside={<span className={cn('source-label',s.metrics_source==='agent'?'green':'')}>{s.mode==='agent'?'عامل پایش':'ثبت دستی'}</span>}><p className="server-host" dir="ltr">{s.host||'آدرس ثبت نشده'}</p><Gauge name="پردازنده (CPU)" value={m?numeric(m.cpu?.usagePercent):null} detail={m?.cpu?.cores?fmt.format(m.cpu.cores)+' هسته':'اطلاعات پردازنده'}/><Gauge name="حافظه (RAM)" value={ram} detail={m?`${fmt.format(numeric(m.memory.used)/1073741824)} از ${fmt.format(numeric(m.memory.total)/1073741824)} گیگابایت`:'بدون داده'}/><Gauge name="فضای دیسک" value={disk} detail={m?`${fmt.format(numeric(m.disk.used)/1073741824)} از ${fmt.format(numeric(m.disk.total)/1073741824)} گیگابایت`:'بدون داده'}/><div className="server-time">{s.metrics_at?'آخرین اندازه‌گیری: '+faDate(s.metrics_at):'هنوز اندازه‌گیری ثبت نشده است'}</div><div className="server-buttons"><button className="button small" onClick={()=>metrics(s)}><Cpu size={15}/> منابع</button><button className="button small" onClick={()=>connect(s)}><Link2 size={15}/> اتصال</button><button className="button small" disabled={busy||s.mode!=='agent'} onClick={()=>poll(s)}><RefreshCw size={15}/> پایش</button><button className="icon-button" onClick={()=>edit(s)}><Pencil size={16}/></button><button className="icon-button danger" onClick={()=>del(s)}><Trash2 size={16}/></button></div></Panel>})}</div>{!servers.length&&<Panel title="سرورها"><Empty text="برای شروع، نخستین سرور را ثبت کنید"/></Panel>}</>}
function Finance({data,financeTab,setFinanceTab,income,expenses,remaining,portfolio,noRate,rateBy,currBy,add,edit,del,pay}){
 const [monthFilter,setMonthFilter]=useState('all');const knownMonths=[...new Set(data.transactions.map(x=>x.date?monthKey(x.date):'').filter(Boolean))].sort().reverse();const current=monthKey(new Date());
 const transactions=data.transactions.filter(t=>monthFilter==='all'||monthKey(t.date)===monthFilter);
 const lastTwo=(data.priceHistory||[]).reduce((m,h)=>{(m[h.code]??=[]).push(h);return m},{});
 let priceChange=0,compared=0;
 for(const h of data.holdings){const quotes=lastTwo[h.asset]||[];const last=quotes.find(x=>Number(x.rn)===1),prev=quotes.find(x=>Number(x.rn)===2),current=rateBy[h.asset]?.price;
  if(last&&prev&&current&&Math.abs(numeric(current)-numeric(last.price_toman))<0.01){priceChange+=numeric(h.quantity)*(numeric(last.price_toman)-numeric(prev.price_toman));compared++}
 }

 const totalsByMonth=knownMonths.slice(0,6).reverse().map(m=>({month:m,income:data.transactions.filter(t=>monthKey(t.date)===m&&t.type==='income').reduce((s,t)=>s+numeric(t.amount),0),expense:data.transactions.filter(t=>monthKey(t.date)===m&&t.type!=='income').reduce((s,t)=>s+numeric(t.amount),0)}));
 const maxMonth=Math.max(1,...totalsByMonth.map(x=>Math.max(x.income,x.expense)));
 return <><div className="stats-grid compact"><Stat title="درآمد ماه جاری" number={shortMoney(income)} suffix="تومان" icon={TrendingUp} tone="green"/><Stat title="هزینه ماه جاری" number={shortMoney(expenses)} suffix="تومان" icon={TrendingDown} tone="orange"/><Stat title="ارزش پس‌انداز" number={shortMoney(portfolio)} suffix="تومان" icon={Wallet} tone="blue"/><Stat title="اقساط باقیمانده" number={shortMoney(remaining)} suffix="تومان" icon={CalendarDays} tone="violet"/></div>
 <div className="tabs finance-tabs">{[['transactions','تراکنش‌ها'],['installments','اقساط'],['savings','پس‌انداز'],['currencies','ارزها و نمادها']].map(([v,t])=><button key={v} className={v===financeTab?'selected':''} onClick={()=>setFinanceTab(v)}>{t}</button>)}</div>
 {financeTab==='transactions'&&<div className="cols-2 finance-layout"><Panel title="دخل و خرج" aside={<div className="panel-buttons"><select aria-label="فیلتر ماه" value={monthFilter} onChange={e=>setMonthFilter(e.target.value)}><option value="all">همه ماه‌ها</option>{knownMonths.map(m=><option key={m} value={m}>{m}</option>)}</select><button className="primary small" onClick={()=>add('transactions')}><Plus size={15}/> تراکنش</button></div>}><div className="records">{transactions.map(t=><div className="record" key={t.id}><span className={cn('tx-symbol',t.type==='income'?'positive':'negative')}>{t.type==='income'?<TrendingUp size={18}/>:<TrendingDown size={18}/>}</span><div className="grow"><strong>{t.description}</strong><small>{faDate(t.date)} · {t.category}</small></div><strong className={t.type==='income'?'good':'danger'}>{t.type==='income'?'+':'−'}{money(t.amount)}</strong><Actions onEdit={()=>edit('transactions',t)} onDelete={()=>del('transactions',t)}/></div>)}{!transactions.length&&<Empty text="تراکنشی ثبت نشده است"/>}</div></Panel><Panel title="روند ماهانه"><div className="legend"><span><i className="legend-green"/>درآمد</span><span><i className="legend-orange"/>هزینه</span></div><div className="bar-chart">{totalsByMonth.map(x=><div key={x.month} className="bar-group"><div className="bar-rails"><div title={money(x.income)} className="bar income" style={{height:(x.income/maxMonth*100)+'%'}}/><div title={money(x.expense)} className="bar expense" style={{height:(x.expense/maxMonth*100)+'%'}}/></div><small>{x.month}</small></div>)}{!totalsByMonth.length&&<Empty text="برای نمودار، تراکنش ثبت کنید"/>}</div><div className="line-item"><strong>مانده جریان نقدی ماه جاری</strong><strong className={income-expenses>=0?'good':'danger'}>{money(income-expenses)}</strong></div></Panel></div>}
 {financeTab==='installments'&&<Panel title="اقساط و تعهدات" aside={<button className="primary small" onClick={()=>add('installments')}><Plus size={15}/> افزودن قسط</button>}><div className="installment-grid">{data.installments.map(x=><div className="installment" key={x.id}><div className="installment-title"><strong>{x.title}</strong><Actions onEdit={()=>edit('installments',x)} onDelete={()=>del('installments',x)}/></div><div className="installment-amount"><span>کل: {money(x.total)}</span><strong>باقیمانده: {money(Math.max(0,numeric(x.total)-numeric(x.paid)))}</strong></div><Progress value={pct(x.paid,x.total)}/><div className="installment-amount"><small>پرداخت‌شده: {money(x.paid)}</small><small>موعد: {faDate(x.due_date)}</small></div><button className="button full small" disabled={numeric(x.paid)>=numeric(x.total)} onClick={()=>pay(x)}>ثبت پرداخت قسط</button></div>)}{!data.installments.length&&<Empty text="هیچ برنامه قسطی ثبت نشده است"/>}</div></Panel>}
 {financeTab==='savings'&&<><Panel title="ترکیب پس‌انداز" aside={<button className="primary small" onClick={()=>add('holdings')}><Plus size={15}/> افزودن دارایی</button>}><div className="saving-summary"><span>جمع ارزش دارایی‌های دارای نرخ</span><strong>{money(portfolio)}</strong>{noRate>0&&<small className="warn">{fmt.format(noRate)} دارایی بدون نرخ معتبر در جمع لحاظ نشده است.</small>}
 {compared>0?<div className="saving-change"><span>تغییر ناشی از آخرین نوبت نرخ (مقدار ثابت، {fmt.format(compared)} دارایی)</span><strong className={priceChange>=0?'good':'danger'}>{priceChange>=0?'+':'−'}{money(Math.abs(priceChange))}</strong></div>:<small>برای محاسبه تغییر ارزش، حداقل دو نوبت نرخ معتبر لازم است.</small>}</div><div className="table-scroller"><table><thead><tr><th>دارایی</th><th>مقدار</th><th>نرخ هر واحد (تومان)</th><th>ارزش روز (تومان)</th><th>منبع نرخ</th><th>عملیات</th></tr></thead><tbody>{data.holdings.map(h=>{const a=currBy[h.asset]||{};const r=rateBy[h.asset];return <tr key={h.id}><td><span className="asset-name"><span className="asset-icon">{a.symbol||'¤'}</span><div><strong>{a.name||h.asset}</strong><small>{h.asset}</small></div></span></td><td>{fmt.format(numeric(h.quantity))} {a.unit}</td><td>{r?.price?money(r.price):'بدون نرخ'}</td><td><strong>{r?.price?money(numeric(h.quantity)*numeric(r.price)):'—'}</strong></td><td><RateSource rate={r}/></td><td><Actions onEdit={()=>edit('holdings',h)} onDelete={()=>del('holdings',h)}/></td></tr>})}</tbody></table>{!data.holdings.length&&<Empty text="برای محاسبه پس‌انداز، مقدار دلار، تتر، طلا یا ارز دیگر را ثبت کنید"/>}</div></Panel><p className="helper-text">ارقام برحسب تومان است؛ منبع نرخ‌آرا: <a href="https://nerkhara.com/" target="_blank" rel="noopener noreferrer">NerkhAra</a>. مقدار دارایی با تغییر نرخ ثابت می‌ماند. ارزش تومانی هر دارایی از «مقدار × نرخ هر واحد به تومان» به‌دست می‌آید.</p></>}
 {financeTab==='currencies'&&<Panel title="فهرست ارزها، طلا و نمادها" aside={<button className="primary small" onClick={()=>add('currencies')}><Plus size={15}/> ارز جدید</button>}><div className="table-scroller"><table><thead><tr><th>نام ارز</th><th>کد</th><th>واحد</th><th>نرخ (تومان)</th><th>منبع نرخ</th><th>کد نوسان</th><th>نماد ارزدیجیتال</th><th>شناسه نرخ‌آرا</th><th>ویرایش</th></tr></thead><tbody>{data.currencies.map(c=><tr key={c.code}><td><span className="asset-name"><span className="asset-icon">{c.symbol}</span><strong>{c.name}</strong></span></td><td dir="ltr">{c.code}</td><td>{c.unit}</td><td>{rateBy[c.code]?.price?money(rateBy[c.code].price):'بدون نرخ'}</td><td><RateSource rate={rateBy[c.code]}/></td><td dir="ltr">{c.navasan_code||'—'}</td><td dir="ltr">{c.arzdigital_code||c.code}</td><td dir="ltr">{c.nerkhara_id||'خودکار'}</td><td><div className="row-actions"><button title="ویرایش" onClick={()=>edit('currencies',c)}><Pencil size={16}/></button>{!c.is_default&&<button className="danger" onClick={()=>del('currencies',c)}><Trash2 size={16}/></button>}</div></td></tr>)}</tbody></table></div><p className="helper-text">قیمت هر واحد، تومان است. نرخ دستی بر نرخ دریافتی API اولویت دارد. منبع نرخ‌آرا: <a href="https://nerkhara.com/" target="_blank" rel="noopener noreferrer">NerkhAra</a>؛ زمان نرخ کنار منبع نوشته شده است. مقدار «۱» برای تومان در نظر گرفته شده است.</p></Panel>}
 </>
}
function Owasp({data,search,setSearch,edit,del,check}){
 const [expanded,setExpanded]=useState('A01');const filtered=data.chapters.filter(c=>(c.title+' '+c.code+' '+c.en+' '+c.notes).toLowerCase().includes(search.toLowerCase()));const completed=data.chapters.filter(c=>c.status==='done').length;
 return <><div className="stats-grid compact"><Stat title="فصل‌های آموزشی" number={fmt.format(data.chapters.length)} icon={BookOpen} tone="blue"/><Stat title="فصل‌های تکمیل‌شده" number={fmt.format(completed)} icon={Check} tone="green"/><Stat title="منابع ثبت‌شده" number={fmt.format(data.resources.length)} icon={Link2} tone="violet"/><Stat title="نیازمند بررسی" number={fmt.format(data.resources.filter(r=>r.status!=='verified').length+data.topics.filter(t=>t.status==='review').length)} icon={AlertTriangle} tone="orange"/></div><div className="toolbar"><div className="search"><Search size={17}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="جست‌وجوی فصل و یادداشت"/></div><a className="button small" href="https://top10.owasp.org/2025/" target="_blank" rel="noopener noreferrer"><ExternalLink size={15}/> مرجع رسمی OWASP 2025</a></div><Panel title="فصل‌ها و مباحث دوره" aside={<span className="count-label">پیشرفت {fmt.format(pct(completed,data.chapters.length).toFixed(0))}٪</span>}><div className="chapters">{filtered.map(c=>{const expandedNow=expanded===c.id;const topics=data.topics.filter(t=>t.chapter_id===c.id),resources=data.resources.filter(r=>r.chapter_id===c.id);return <div className="chapter" key={c.id}><button className="chapter-top" aria-expanded={expandedNow} onClick={()=>setExpanded(expandedNow?'':c.id)}><span className="chapter-code">{c.code}</span><div className="grow"><strong>{c.title}</strong><small dir="ltr" style={{textAlign:'right'}}>{c.en}</small></div><Status value={c.status}/><ChevronDown size={18} className={expandedNow?'chevron-up':''}/></button>{expandedNow&&<div className="chapter-body"><div className="chapter-actions"><span className="helper-text">{c.verified?'صحت فصل تأیید شده است':'نیازمند بررسی و تأیید صحت فصل'}</span><button className="button small" onClick={()=>edit('chapters',c)}><Pencil size={14}/> ویرایش فصل / یادداشت</button><button className="button small" onClick={()=>edit('topics',null,{chapter_id:c.id})}><Plus size={14}/> مبحث</button><button className="button small" onClick={()=>edit('resources',null,{chapter_id:c.id})}><Plus size={14}/> منبع</button>{!c.id.startsWith('A0')&&<button className="icon-button danger" onClick={()=>del('chapters',c)}><Trash2 size={15}/></button>}</div>{c.description&&<p className="chapter-note">{c.description}</p>}{c.notes&&<div className="notes-box"><strong>یادداشت‌های این فصل</strong><p>{c.notes}</p></div>}<h3>مباحث و وضعیت مطالعه</h3>{topics.length?topics.map(t=><div key={t.id} className="resource"><CircleCheck size={17}/><div className="grow"><strong>{t.title}</strong><small>{t.notes||'بدون یادداشت'}</small></div><Status value={t.status}/><Actions onEdit={()=>edit('topics',t)} onDelete={()=>del('topics',t)}/></div>):<p className="helper-text">هنوز مبحثی ثبت نشده است.</p>}<h3>منابع و لینک‌ها</h3>{resources.map(r=><div key={r.id} className="resource"><Link2 size={17}/><div className="grow"><a href={r.url} target="_blank" rel="noopener noreferrer">{r.title} <ExternalLink size={13}/></a><small>{r.notes||r.url} · {r.checked_at?'آخرین بررسی: '+faDate(r.checked_at):'بررسی خودکار انجام نشده'}</small></div><Status value={r.status}/><button className="button xs" onClick={()=>check(r)}>بررسی لینک</button><Actions onEdit={()=>edit('resources',r)} onDelete={()=>del('resources',r)}/></div>)}</div>}</div>})}{!filtered.length&&<Empty text="فصل مورد نظر یافت نشد"/>}</div></Panel></>
}
function Settings({provider,arzdigital,rateSource,username,usernameOpen,providerOpen,arzdigitalOpen,rateSourceOpen,passwordOpen,importOpen,exportData,busy}){return <div className="settings-grid"><Panel title="کلیدها و API نرخ ارز"><div className="settings-row"><span className="settings-icon"><RefreshCw size={20}/></span><div className="grow"><strong>منبع فعال نرخ‌ها</strong><p>{({nerkhara:'نرخ‌آرا (رایگان؛ بدون کلید)',arzdigital:'ارزدیجیتال (کلید اختصاصی)',navasan:'نوسان (کلید اختصاصی)'})[rateSource.selected]||'نامشخص'}</p><small>فقط منبع انتخاب‌شده نرخ‌ها را به‌روزرسانی می‌کند. نرخ دستی همیشه اولویت دارد. هنگام اختلال، نرخ قبلی با زمان واقعی حفظ می‌شود.</small></div><button className="button" onClick={rateSourceOpen}><SlidersHorizontal size={16}/> تغییر منبع</button></div><div className="settings-row"><span className="settings-icon"><Coins size={20}/></span><div className="grow"><strong>NerkhAra · نرخ‌آرا</strong><p>رایگان، بدون کلید API · هر {fmt.format(rateSource.refreshMinutes)} دقیقه در حالت منبع فعال · قیمت به تومان</p><small>ارزهای رایج، طلا، سکه و رمزارز؛ <a href="https://nerkhara.com/en/api/" target="_blank" rel="noopener noreferrer">مستندات رسمی</a> · منبع قیمت: <a href="https://nerkhara.com/" target="_blank" rel="noopener noreferrer">NerkhAra</a></small></div><span className="status status-verified">آماده استفاده</span></div><div className="settings-row"><span className="settings-icon"><KeyRound size={20}/></span><div className="grow"><strong>سرویس نرخ نوسان</strong><p>وضعیت: {provider.configured?'کلید فعال است':'کلید وارد نشده'} · واحد منبع: {provider.unit==='RIAL'?'ریال ← تبدیل به تومان':'تومان'} · هر {fmt.format(provider.refreshHours)} ساعت</p><small>کلید در دیتابیس به‌صورت رمزگذاری‌شده نگهداری می‌شود و در خروجی نمایش داده نمی‌شود.</small></div><button className="button" onClick={providerOpen}><SlidersHorizontal size={16}/> تنظیم API</button></div><div className="settings-row"><span className="settings-icon"><Coins size={20}/></span><div className="grow"><strong>API رسمی ارزدیجیتال</strong><p>وضعیت: {arzdigital.enabled?(arzdigital.configured?'فعال و دارای کلید':'فعال، کلید تنظیم نشده'):'غیرفعال'} · واحد: {arzdigital.unit==='RIAL'?'ریال → تومان':'تومان'} · هر {fmt.format(arzdigital.refreshHours)} ساعت</p><small>دریافت کلید از <a href="https://console.arzdigital.com/" target="_blank" rel="noopener noreferrer">کنسول رسمی ارزدیجیتال</a>؛ نشانی endpoint و فیلدهای JSON باید طبق مستندات سرویس تنظیم شوند. کلید در سرور رمزگذاری می‌شود و در مرورگر نمایش داده نمی‌شود.</small></div><button className="button" onClick={arzdigitalOpen}><SlidersHorizontal size={16}/> اتصال ارزدیجیتال</button></div></Panel><Panel title="امنیت حساب"><div className="settings-row"><span className="settings-icon"><KeyRound size={20}/></span><div className="grow"><strong>نام کاربری مدیر: <span dir="ltr">{username}</span></strong><p>نام کاربری با تأیید رمز فعلی قابل تغییر است.</p></div><button className="button" onClick={usernameOpen}><Pencil size={16}/> تغییر نام کاربری</button></div><div className="settings-row"><span className="settings-icon"><ShieldCheck size={20}/></span><div className="grow"><strong>رمز ورود مدیر</strong><p>نشست‌های مدیریت روی سرور کنترل می‌شوند. پس از تغییر رمز، نشست‌ها باطل می‌شوند.</p></div><button className="button" onClick={passwordOpen}><KeyRound size={16}/> تغییر رمز</button></div></Panel><Panel title="پشتیبان‌گیری و بازیابی"><div className="settings-row"><span className="settings-icon"><Database size={20}/></span><div className="grow"><strong>پشتیبان JSON اطلاعات</strong><p>خروجی وظایف، سرورها، تراکنش‌ها، ارزها، منابع و یادداشت‌ها؛ بدون کلیدهای API و توکن‌ها.</p></div><div className="settings-buttons"><button className="button" onClick={exportData}><Download size={16}/> دریافت</button><button className="button" disabled={busy} onClick={importOpen}><Upload size={16}/> ورود اطلاعات</button></div></div><p className="helper-text">برای پشتیبان کامل PostgreSQL از ابزار pg_dump استفاده کنید. قابلیت واردکردن JSON برای انتقال داده‌های برنامه طراحی شده است.</p></Panel><Panel title="نصب به‌عنوان وب‌اپ"><div className="settings-row"><span className="settings-icon"><LayoutDashboard size={20}/></span><div className="grow"><strong>برنامه قابل نصب (PWA)</strong><p>روی موبایل یا دسکتاپ از گزینه «افزودن به صفحه اصلی» یا «Install app» در مرورگر استفاده کنید.</p><small>ساختار برنامه در حالت آفلاین ممکن است باز شود، اما مشاهده و ویرایش داده‌ها به اتصال سرور نیاز دارد.</small></div></div></Panel><Panel title="دیتابیس و استقرار"><div className="settings-row"><span className="settings-icon"><Database size={20}/></span><div className="grow"><strong>PostgreSQL + Docker Compose</strong><p>داده‌های عملیاتی در جداول رابطه‌ای SQL و روی volume مستقل PostgreSQL ذخیره می‌شوند.</p><small>دامنه و HTTPS توسط Caddy مدیریت می‌شوند.</small></div></div></Panel></div>}
const OPT={status:[['todo','شروع نشده'],['progress','در حال انجام'],['review','نیازمند بررسی'],['done','انجام‌شده']],priority:[['low','کم'],['medium','متوسط'],['high','زیاد']],category:[['work','کاری'],['personal','شخصی'],['server','سرور'],['owasp','آموزش OWASP'],['finance','مالی']],environment:[['production','Production'],['staging','Staging'],['development','Development'],['other','سایر']],mode:[['manual','ثبت دستی'],['agent','عامل پایش']],type:[['expense','هزینه'],['income','درآمد'],['installment','پرداخت قسط']],verified:[['false','تأیید نشده'],['true','تأیید شده']],unit:[['RIAL','ریال (تقسیم خودکار بر ۱۰)'],['TOMAN','تومان']],resourceStatus:[['pending','در انتظار بررسی'],['verified','معتبر و بررسی‌شده'],['broken','نامعتبر'],['review','نیازمند بررسی']]};
const F=(name,label,type='text',extra={})=>({name,label,type,...extra});
function editorFields(kind,item,data,extras,provider,arzdigital,rateSource){const it=item||{},date=new Date().toISOString().slice(0,10);switch(kind){
 case 'tasks':return [F('title','عنوان کار','text',{required:true,maxLength:180}),F('category','دسته‌بندی','select',{options:OPT.category,defaultValue:'work'}),F('status','وضعیت','select',{options:OPT.status,defaultValue:'todo'}),F('priority','اولویت','select',{options:OPT.priority,defaultValue:'medium'}),F('due_date','موعد انجام','date'),F('notes','یادداشت','textarea')];
 case 'servers':return [F('name','نام سرور','text',{required:true}),F('host','آدرس / IP','text'),F('environment','محیط','select',{options:OPT.environment,defaultValue:'production'}),F('mode','روش ثبت منابع','select',{options:OPT.mode,defaultValue:'manual'}),F('notes','توضیحات سرور','textarea')];
 case 'transactions':return [F('type','نوع تراکنش','select',{options:OPT.type,defaultValue:'expense'}),F('amount','مبلغ به تومان','number',{required:true,min:'0.01',step:'any'}),F('date','تاریخ','date',{required:true,defaultValue:date}),F('category','گروه هزینه یا درآمد','text',{defaultValue:'عمومی'}),F('description','شرح تراکنش','text',{required:true})];
 case 'installments':return [F('title','عنوان تعهد / قسط','text',{required:true}),F('total','کل تعهد (تومان)','number',{required:true,min:'0',step:'any'}),F('paid','مبلغ پرداخت‌شده تا امروز','number',{min:'0',step:'any',defaultValue:'0'}),F('monthly','مبلغ هر قسط','number',{min:'0',step:'any',defaultValue:'0'}),F('due_date','سررسید بعدی','date'),F('notes','توضیحات','textarea')];
 case 'holdings':return [F('asset','نوع دارایی','select',{options:data.currencies.map(c=>[c.code,c.symbol+' · '+c.name+' ('+c.unit+')']),defaultValue:'USD'}),F('quantity','مقدار دارایی','number',{required:true,min:'0',step:'any'}),F('note','توضیحات دارایی','textarea')];
 case 'currencies':return [F('code','کد ارز (مثلاً CHF)','text',{required:!item,maxLength:12,disabled:!!item,defaultValue:it.code||''}),F('name','نام ارز یا دارایی','text',{required:true}),F('symbol','نماد (مثل € یا ₿)','text',{required:true,maxLength:16}),F('unit','واحد دارایی','text',{required:true,defaultValue:'واحد'}),F('navasan_code','کد نماد نوسان (اختیاری)','text'),F('arzdigital_code','نماد ارزدیجیتال (اختیاری؛ مثل BTC یا USD)','text',{maxLength:32}),F('nerkhara_id','شناسه نرخ‌آرا (اختیاری؛ مانند gold-18k یا usd)','text',{maxLength:48,placeholder:'gold-18k'}),F('manual_toman','قیمت هر واحد به تومان','number',{step:'any',min:'0'})];
 case 'chapters':return [F('code','کد فصل','text',{defaultValue:'CUSTOM'}),F('title','عنوان فارسی','text',{required:true}),F('en','عنوان انگلیسی','text'),F('description','توضیح فصل','textarea'),F('status','وضعیت مطالعه','select',{options:OPT.status,defaultValue:'todo'}),F('verified','صحت‌سنجی فصل','select',{options:OPT.verified,defaultValue:'false'}),F('notes','یادداشت‌های فصل','textarea')];
 case 'topics':return [F('title','نام مبحث','text',{required:true}),F('status','وضعیت','select',{options:OPT.status,defaultValue:'todo'}),F('verified','وضعیت صحت‌سنجی','select',{options:OPT.verified,defaultValue:'false'}),F('notes','یادداشت آموزشی','textarea')];
 case 'resources':return [F('title','عنوان منبع','text',{required:true}),F('url','آدرس HTTPS منبع','url',{required:true}),F('status','وضعیت بررسی','select',{options:OPT.resourceStatus,defaultValue:'pending'}),F('notes','توضیحات و شواهد بررسی','textarea')];
 case 'metrics':{const m=it.metrics||{};return [F('cpu','مصرف CPU درصد','number',{required:true,min:0,max:100,step:'any',defaultValue:m.cpu?.usagePercent??''}),F('cores','تعداد هسته','number',{min:1,step:1,defaultValue:m.cpu?.cores||''}),F('ramTotal','RAM کل (GB)','number',{required:true,min:'0.01',step:'any',defaultValue:m.memory?.total?numeric(m.memory.total)/1073741824:''}),F('ramUsed','RAM مصرفی (GB)','number',{required:true,min:0,step:'any',defaultValue:m.memory?.used?numeric(m.memory.used)/1073741824:''}),F('diskTotal','هارد کل (GB)','number',{required:true,min:'0.01',step:'any',defaultValue:m.disk?.total?numeric(m.disk.total)/1073741824:''}),F('diskUsed','هارد مصرفی (GB)','number',{required:true,min:0,step:'any',defaultValue:m.disk?.used?numeric(m.disk.used)/1073741824:''})]}
 case 'agent':return [F('url','نشانی HTTPS عامل پایش','url',{required:true,placeholder:'https://metrics.example.com'}),F('token','توکن امن عامل','password',{required:true,minLength:16})];
 case 'payment':return [F('amount','مبلغ پرداخت (تومان)','number',{required:true,min:'0.01',step:'any',defaultValue:Math.min(numeric(it.monthly)||numeric(it.total)-numeric(it.paid),numeric(it.total)-numeric(it.paid))}),F('date','تاریخ','date',{required:true,defaultValue:date})];
 case 'arzdigital':return [F('enabled','فعالسازی دریافت نرخ از ارزدیجیتال','checkbox',{defaultValue:arzdigital.enabled}),F('endpoint','نشانی رسمی API از مستندات ارزدیجیتال','url',{defaultValue:arzdigital.endpoint,placeholder:'https://api.arzdigital.com/…'}),F('key','کلید جدید API (خالی = حفظ کلید فعلی)','password'),F('authStyle','روش ارسال کلید','select',{options:[['bearer','Authorization: Bearer'],['x-api-key','X-API-Key']],defaultValue:arzdigital.authStyle||'bearer'}),F('unit','واحد قیمت از منبع','select',{options:OPT.unit,defaultValue:arzdigital.unit||'TOMAN'}),F('refreshHours','فاصله دریافت نرخ (ساعت)','number',{required:true,min:1,max:168,defaultValue:arzdigital.refreshHours||8}),F('rootPath','مسیر داده در JSON (مثلاً data یا data.rates؛ خالی = ریشه)','text',{defaultValue:arzdigital.rootPath??'data'}),F('codeField','نام فیلد نماد در JSON (برای آرایه‌ها)','text',{defaultValue:arzdigital.codeField||'symbol'}),F('priceField','نام فیلد قیمت در JSON','text',{defaultValue:arzdigital.priceField||'price'}),F('clearKey','حذف کلید موجود','checkbox')];
 case 'rateSource':return [F('selected','منبع اصلی دریافت نرخ‌ها','select',{options:[['nerkhara','NerkhAra · رایگان و بدون کلید'],['arzdigital','ارزدیجیتال · کلید API'],['navasan','نوسان · کلید API']],defaultValue:rateSource.selected||'nerkhara'}),F('refreshMinutes','بازه نرخ‌آرا (دقیقه)','number',{required:true,min:10,max:1440,defaultValue:rateSource.refreshMinutes||15})];
 case 'provider':return [F('key','کلید جدید API نوسان (خالی = بدون تغییر)','password'),F('unit','واحد دادهٔ API','select',{options:OPT.unit,defaultValue:provider.unit||'RIAL'}),F('refreshHours','فاصله دریافت قیمت (ساعت)','number',{required:true,min:1,max:168,defaultValue:provider.refreshHours||8}),F('clearKey','حذف کلید موجود','checkbox')];
 case 'username':return [F('username','نام کاربری جدید (۳ تا ۳۲ نویسه لاتین)','text',{required:true,minLength:3,maxLength:32}),F('current','رمز فعلی مدیر برای تأیید','password',{required:true})];
 case 'password':return [F('current','رمز فعلی','password',{required:true}),F('password','رمز جدید (حداقل ۱۲ نویسه)','password',{required:true,minLength:12}),F('confirm','تکرار رمز جدید','password',{required:true,minLength:12})];
 case 'import':return [F('file','محتوای فایل JSON پشتیبان','import')];
 default:return [];
}}
const titleKind={tasks:'کار',servers:'سرور',transactions:'تراکنش',installments:'قسط',holdings:'دارایی',currencies:'ارز و نماد',chapters:'فصل OWASP',topics:'مبحث',resources:'منبع',metrics:'مصرف منابع',agent:'عامل پایش',payment:'پرداخت قسط',provider:'تنظیمات API نوسان',arzdigital:'تنظیمات API ارزدیجیتال',rateSource:'انتخاب منبع نرخ ارز',username:'تغییر نام کاربری',password:'تغییر رمز',import:'بازیابی اطلاعات'};
function Editor({config,data,provider,arzdigital,rateSource,close,busy,save}){
 const {kind,item,extras}=config;const fields=editorFields(kind,item,data,extras,provider,arzdigital,rateSource);const [vals,setVals]=useState(()=>Object.fromEntries(fields.map(f=>{const v=item?.[f.name]??(f.name==='due_date'?item?.dueDate:null)??f.defaultValue??(f.type==='checkbox'?false:'');return [f.name,f.type==='date'?dateOnly(v):f.name==='verified'?String(v):v]})));const [importing,setImporting]=useState(false),[localErr,setLocalErr]=useState('');
 const change=(k,v)=>setVals(cur=>({...cur,[k]:v}));
 const submit=async e=>{e.preventDefault();setLocalErr('');try{if(kind==='username'&&!/^[a-zA-Z][a-zA-Z0-9_.-]{2,31}$/.test(vals.username))throw Error('نام کاربری باید ۳ تا ۳۲ نویسه لاتین و با حرف شروع شود');if(kind==='password'&&vals.password!==vals.confirm)throw Error('تکرار رمز با رمز جدید یکسان نیست');if(kind==='currencies'&&item)delete vals.code;if(kind==='currencies'&&!item){vals.code=String(vals.code).toUpperCase();if(!/^[A-Z0-9]{2,12}$/.test(vals.code))throw Error('کد ارز فقط ۲ تا ۱۲ نویسه لاتین یا عدد باشد')};if(kind==='topics'||kind==='chapters')vals.verified=vals.verified==='true'||vals.verified===true;if(kind==='metrics'&&(numeric(vals.ramUsed)>numeric(vals.ramTotal)||numeric(vals.diskUsed)>numeric(vals.diskTotal)))throw Error('مصرف منابع بیشتر از ظرفیت کل است');await save({...vals})}catch(err){setLocalErr(err.message)}};
 return <div className="modal-overlay" onMouseDown={e=>{if(e.target===e.currentTarget)close()}}><div className="modal" role="dialog" aria-modal="true"><div className="modal-header"><div><p className="eyebrow">ویرایش اطلاعات</p><h2>{item?'ویرایش ':'افزودن '}{titleKind[kind]}</h2></div><button className="icon-button" title="بستن" onClick={close}><X size={20}/></button></div><form className="form" onSubmit={submit}><div className="modal-fields">{fields.map(f=><label key={f.name} className={cn('field',f.type==='textarea'||f.type==='import'?'wide':'')}><span>{f.label}</span>{f.type==='select'?<select value={vals[f.name]??''} onChange={e=>change(f.name,e.target.value)} required={f.required}>{f.options.map(([v,t])=><option key={v} value={v}>{t}</option>)}</select>:f.type==='textarea'?<textarea value={vals[f.name]??''} rows={4} onChange={e=>change(f.name,e.target.value)}/>:f.type==='import'?<input type="file" accept="application/json,.json" onChange={async e=>{setImporting(true);try{const f=e.target.files?.[0];if(f&&f.size>5*1024*1024)throw Error('حداکثر اندازه فایل پشتیبان ۵ مگابایت است');const txt=await f?.text();change('file',txt||'')}catch(err){window.alert(err.message)}finally{setImporting(false)}}} required/>:f.type==='checkbox'?<input type="checkbox" checked={Boolean(vals[f.name])} onChange={e=>change(f.name,e.target.checked)}/>:<input dir={f.name==='code'||f.name==='navasan_code'||f.name==='arzdigital_code'||f.name==='nerkhara_id'||f.type==='url'?'ltr':undefined} type={f.type} placeholder={f.placeholder} required={f.required} min={f.min} max={f.max} step={f.step} minLength={f.minLength} maxLength={f.maxLength} disabled={f.disabled} value={vals[f.name]??''} onChange={e=>change(f.name,e.target.value)}/>}</label>)}</div>{kind==='rateSource'&&<p className="helper-text">نرخ‌آرا رایگان و بدون کلید است. در صورت انتخاب ارزدیجیتال، ابتدا آن سرویس را از تنظیمات فعال کنید. نرخ‌های قبلی تا دریافت موفق منبع جدید حفظ می‌شوند.</p>}{kind==='arzdigital'&&<p className="helper-text">این اتصال فقط با کلید مجاز و endpoint رسمی فعال می‌شود. قیمت‌ها به تومان ذخیره می‌شوند؛ مسیر JSON و واحد را دقیقاً مطابق مستندات API تنظیم کنید. منبع نرخ و زمان آخرین به‌روزرسانی نمایش داده می‌شود. نرخ دستی همچنان اولویت دارد.</p>}{kind==='provider'&&<p className="helper-text">کلید API سمت سرور رمزگذاری می‌شود؛ در فایل پشتیبان ذخیره نمی‌شود. نرخ‌های بازار ایران پس از دریافت API برحسب تومان محاسبه می‌شوند.</p>}{kind==='import'&&<p className="helper-text">ورود داده‌ها فقط زمانی امکان‌پذیر است که هنوز تراکنش، وظیفه، دارایی یا سروری در دیتابیس جدید ثبت نشده باشد.</p>}{localErr&&<p className="form-error">{localErr}</p>}<div className="modal-footer"><button className="button" type="button" onClick={close}>انصراف</button><button className="primary" type="submit" disabled={busy||importing}><Save size={16}/> ذخیره اطلاعات</button></div></form></div></div>;
}

createRoot(document.getElementById('root')).render(<App/>);
